"""Read-only local dashboard for the runner."""

DASHBOARD = """<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>3lotus | Runner</title><style>
:root{color-scheme:dark;--lotus-bg:#07090d;--lotus-sidebar:#0a0e14;--lotus-surface:#0f141c;--lotus-surface-raised:#151c26;--lotus-border:#283242;--lotus-text:#edf2f7;--lotus-muted:#9ba9ba;--lotus-accent:#43d398;--lotus-accent-surface:#1b2634;--lotus-warning:#f6c667;--lotus-danger:#ff6b81;--lotus-info:#64b5ff;--lotus-space-1:4px;--lotus-space-2:8px;--lotus-space-3:12px;--lotus-space-4:16px;--lotus-space-6:24px;--lotus-space-8:32px;--lotus-radius-control:6px;--lotus-radius-card:8px;--lotus-radius-surface:12px;--lotus-sidebar-width:248px;--lotus-topbar-height:64px;--lotus-content-max:1360px;--lotus-control-target:40px;--lotus-navigation-target:44px;--lotus-font-family:Inter,ui-sans-serif,system-ui,sans-serif;--bg:var(--lotus-bg);--panel:var(--lotus-surface);--line:var(--lotus-border);--text:var(--lotus-text);--muted:var(--lotus-muted);--green:var(--lotus-accent);--yellow:var(--lotus-warning)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px var(--lotus-font-family)}:where(a,button,input,select,textarea,[tabindex]):focus-visible{outline:2px solid var(--lotus-accent);outline-offset:2px}:where(time,output,[data-numeric]){font-variant-numeric:tabular-nums}
.shell{display:grid;grid-template-columns:var(--lotus-sidebar-width) minmax(0,1fr);min-height:100vh}.sidebar{padding:22px 16px;background:#0a0e14;border-right:1px solid var(--line)}
.brand{display:flex;align-items:center;gap:11px;min-height:54px;padding:0 10px;font-size:13px;font-weight:800;letter-spacing:.13em}.brand img{width:38px;height:38px;object-fit:contain;filter:brightness(0) invert(1)}
nav{display:grid;gap:5px;margin-top:0}nav a{color:#929db0;text-decoration:none;border:1px solid transparent;padding:0 12px;border-radius:8px}nav a:hover{background:rgba(255,255,255,.045);color:#fff}nav a.active{background:#1b2634;color:#fff;border-color:transparent;box-shadow:inset 3px 0 0 #43d398}
main{padding:28px;max-width:var(--lotus-content-max);width:100%;margin:auto}.eyebrow{text-transform:uppercase;letter-spacing:.12em;font-size:11px;color:var(--green)}
h1{margin:6px 0 8px;font-size:30px}.sub{color:var(--muted);margin-bottom:30px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px}
.card{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:20px}.card span{display:block;color:var(--muted);font-size:13px}.card strong{display:block;font-size:28px;margin-top:12px;font-variant-numeric:tabular-nums}
h2{font-size:18px;margin:32px 0 14px}.list{display:grid;gap:10px}.row{display:flex;justify-content:space-between;gap:18px;border-bottom:1px solid var(--line);padding:10px 0}.muted{color:var(--muted)}.ok{color:var(--green)}.warn{color:var(--yellow)}
.data-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 24px;margin:0}.data-row{display:grid;grid-template-columns:minmax(120px,.8fr) minmax(0,1.2fr);gap:12px;padding:12px 0;border-bottom:1px solid var(--line)}.data-row dt{color:var(--muted);font-size:13px}.data-row dd{margin:0;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}.empty-state{margin:0;color:var(--muted);line-height:1.5}@media(max-width:700px){.shell{display:block}.sidebar{border-right:0;border-bottom:1px solid var(--line);padding:16px}nav{display:flex;overflow:auto;margin-top:15px}nav a{white-space:nowrap}main{padding:22px 16px}.data-list{grid-template-columns:1fr}.data-row{grid-template-columns:minmax(105px,.8fr) minmax(0,1.2fr)}}
.sidebar{position:sticky;top:0;display:flex;flex-direction:column;height:100vh;padding:24px 16px}.brand{font-size:13px;letter-spacing:.13em}.workspace-label{padding:14px 12px;margin:12px 0 14px;border:0;border-top:1px solid var(--line);color:var(--muted);font-size:11px;letter-spacing:.08em;text-transform:uppercase}.workspace-label strong{display:block;margin-top:6px;color:var(--text);font-size:13px;letter-spacing:0;text-transform:none}nav{margin-top:0;gap:5px}nav a{display:flex;align-items:center;gap:11px;min-height:44px;padding:0 12px;font-size:13px;font-weight:650}nav a svg{width:19px;height:19px;flex:none;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}.sidebar-footer{margin-top:auto;padding:16px 12px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}.workspace{min-width:0}.topbar{position:sticky;top:0;z-index:10;display:flex;align-items:center;gap:14px;height:var(--lotus-topbar-height);padding:0 26px;border-bottom:1px solid var(--line);background:rgba(10,14,20,.94)}.topbar small{display:block;color:var(--muted);font-size:11px}.topbar strong{display:block;margin-top:2px;font-size:15px}.topbar .mode{margin-left:auto;padding:6px 9px;border:1px solid #27795b;border-radius:999px;color:var(--green);font-size:10px;font-weight:800}.menu-toggle{display:none;width:40px;height:40px;border:1px solid var(--line);border-radius:6px;background:var(--panel);color:var(--text);font-size:21px}.overlay{display:none}main{padding:24px 24px 32px}.card{border-radius:8px}h2{margin:28px 0 14px}
@media(max-width:860px){.shell{display:block}.sidebar{position:fixed;inset:0 auto 0 0;z-index:20;width:min(280px,85vw);height:100vh;transform:translateX(-100%);transition:transform .2s ease;border-right:1px solid var(--line);border-bottom:0}.sidebar.open{transform:none}.overlay.open{display:block;position:fixed;inset:0;z-index:19;background:#000a}.menu-toggle{display:grid;place-items:center}.topbar{height:60px;padding:0 16px}nav{display:grid;overflow:visible;margin-top:16px}main{padding:20px 16px}}@media(prefers-reduced-motion:reduce){.sidebar{transition:none}}
</style></head><body><div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><img src="/assets/lotus-icon.png" alt=""><span>LOTUS</span></div><div class="workspace-label">Painéis locais<strong>Gold Lotus</strong></div><nav aria-label="Painéis"><a href="//localhost:7771/"><svg viewBox="0 0 24 24" aria-hidden="true"><ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v6c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 11v6c0 1.7 3.6 3 8 3s8-1.3 8-3v-6"/></svg><span>Histórico</span></a><a href="//localhost:7772/workspace"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 20 6v5c0 5-3.4 8-8 10-4.6-2-8-5-8-10V6l8-3Z"/><path d="m9 12 2 2 4-4"/></svg><span>Operation Core</span></a><a class="active" href="//localhost:7773/" aria-current="page"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 5 11 7-11 7V5Z"/></svg><span>Runner</span></a><a href="//localhost:7774/workspace"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 16l9 5 9-5"/></svg><span>Estratégias</span></a><a href="//localhost:7775/workspace"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><span>Pesquisa</span></a><a href="//localhost:7777/"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v17H6.5A2.5 2.5 0 0 0 4 22V5.5ZM4 18a2.5 2.5 0 0 1 2.5-2.5H20"/></svg><span>Documentação</span></a></nav><div class="sidebar-footer">Execução desativada</div></aside><div class="overlay" id="overlay"></div><div class="workspace"><header class="topbar"><button type="button" class="menu-toggle" id="menu-toggle" aria-label="Abrir menu" aria-expanded="false" aria-controls="sidebar">☰</button><div><small>Gold Lotus</small><strong>Runner</strong></div><span class="mode">LOCAL</span></header>
<main><p class="eyebrow">Runner local</p><h1>Painel de execução</h1><p class="sub">Estado do runner e das estratégias. A execução permanece desativada por padrão.</p>
<div class="grid"><article class="card"><span>Serviço</span><strong id="service">Verificando…</strong></article><article class="card"><span>Conta MT5</span><strong id="account">Verificando…</strong></article><article class="card"><span>Estratégias</span><strong id="strategy-count">—</strong></article><article class="card"><span>Execução</span><strong id="execution">—</strong></article></div>
<h2>Estratégias instaladas</h2><section class="card list" id="strategies"><span>Carregando…</span></section><h2>Última decisão</h2><section class="card"><p class="empty-state" id="decision-empty">Aguardando dados…</p><dl class="data-list" id="decision" hidden></dl></section><h2>Métricas</h2><section class="card"><p class="empty-state" id="metrics-empty">Carregando…</p><dl class="data-list" id="metrics" hidden></dl></section><h2>Saúde</h2><section class="card"><p class="empty-state" id="health-empty">Carregando…</p><dl class="data-list" id="health" hidden></dl></section><p class="muted" id="updated"></p></main></div></div>
<script>
const panels=[['Histórico',7771,'/'],['Operation Core',7772,'/workspace'],['Runner',7773,'/'],['Estratégias',7774,'/workspace'],['Pesquisa',7775,'/workspace'],['Documentação',7777,'/']];
const icons={7771:'<svg viewBox="0 0 24 24" aria-hidden="true"><ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v6c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 11v6c0 1.7 3.6 3 8 3s8-1.3 8-3v-6"/></svg>',7772:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 20 6v5c0 5-3.4 8-8 10-4.6-2-8-5-8-10V6l8-3Z"/><path d="m9 12 2 2 4-4"/></svg>',7773:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 5 11 7-11 7V5Z"/></svg>',7774:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5M3 16l9 5 9-5"/></svg>',7775:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>',7777:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v17H6.5A2.5 2.5 0 0 0 4 22V5.5ZM4 18a2.5 2.5 0 0 1 2.5-2.5H20"/></svg>'};
document.querySelector('nav').replaceChildren(...panels.map(([label,port,path])=>{const link=document.createElement('a');link.href=location.protocol+'//'+location.hostname+':'+port+path;link.innerHTML=icons[port]+'<span>'+label+'</span>';if(port===7773){link.className='active';link.setAttribute('aria-current','page')}return link}));
const sidebar=document.getElementById('sidebar'),overlay=document.getElementById('overlay'),toggle=document.getElementById('menu-toggle');function setMenu(open){sidebar.classList.toggle('open',open);overlay.classList.toggle('open',open);toggle.setAttribute('aria-expanded',String(open))}toggle.addEventListener('click',()=>setMenu(!sidebar.classList.contains('open')));overlay.addEventListener('click',()=>setMenu(false));document.addEventListener('keydown',event=>{if(event.key==='Escape')setMenu(false)});
function renderDetails(target,entries,emptyText){target.replaceChildren();const rows=entries.filter(([,value])=>value!==undefined&&value!==null);const empty=target.previousElementSibling;target.hidden=rows.length===0;empty.hidden=rows.length>0;empty.textContent=emptyText;if(!rows.length)return;for(const [label,value] of rows){const row=document.createElement('div');row.className='data-row';const term=document.createElement('dt');term.textContent=label;const detail=document.createElement('dd');detail.textContent=String(value);row.append(term,detail);target.append(row)}}
function formatTimestamp(value){if(!value)return 'Sem atualização';const date=new Date(value);return Number.isNaN(date.getTime())?String(value):date.toLocaleString('pt-BR',{timeZone:'UTC'})+' UTC'}
async function refresh(){try{const paths=['/ready','/api/account','/api/strategies','/api/decisions/latest','/api/metrics','/health'];const [ready,account,strategies,decision,metrics,health]=await Promise.all(paths.map(p=>fetch(p).then(r=>{if(!r.ok)throw Error(p+' '+r.status);return r.json()})));
document.getElementById('service').textContent=ready.status==='ready'?'Pronto':'Indisponível';document.getElementById('service').className=ready.status==='ready'?'ok':'warn';
document.getElementById('account').textContent=account.connected?'Conectada':'Desconectada';document.getElementById('account').className=account.connected?'ok':'warn';document.getElementById('strategy-count').textContent=String(ready.strategies??0);
const execution=document.getElementById('execution');execution.textContent=ready.execution_enabled?'Ativada':'Desativada';execution.className=ready.execution_enabled?'warn':'ok';
const box=document.getElementById('strategies');box.replaceChildren();for(const item of strategies.items){const row=document.createElement('div');row.className='row';const name=document.createElement('span');name.textContent=item.name+' · '+item.version;const state=document.createElement('span');state.textContent=item.runnable?'Pronta':'Inativa';state.className=item.runnable?'ok':'muted';row.append(name,state);box.append(row)}if(!strategies.items.length){const empty=document.createElement('span');empty.className='muted';empty.textContent='Nenhuma estratégia instalada.';box.append(empty)}
const latest=decision.item,actionLabels={buy:'Compra',sell:'Venda',hold:'Aguardar'};renderDetails(document.getElementById('decision'),latest?[['Ação',actionLabels[latest.action]||latest.action],['Motivo',latest.reason],['Tamanho solicitado',latest.size],['Latência',latest.latency_ms==null?latest.decision_latency_ms==null?null:Number(latest.decision_latency_ms).toFixed(1)+' ms':Number(latest.latency_ms).toFixed(1)+' ms'],['Registrada em',formatTimestamp(latest.created_msc?Number(latest.created_msc):null)]]:[],'Nenhuma decisão registrada.');
const age=metrics.last_tick_age_ms;renderDetails(document.getElementById('metrics'),[['Último tick',age==null?'Sem ticks recebidos':(Number(age)/1000).toFixed(1)+' s atrás'],['Ticks recebidos',metrics.ticks_received],['Ticks duplicados',metrics.duplicate_ticks],['Decisões',metrics.decisions_total],['Execuções reportadas',metrics.executions_total],['Eventos pendentes',metrics.telemetry_outbox_pending]],'Métricas indisponíveis.');
renderDetails(document.getElementById('health'),[['Estado',health.status],['Serviço',health.service],['Verificado em',formatTimestamp(health.timestamp_utc)]],'Estado de saúde indisponível.');document.getElementById('updated').textContent='Atualizado às '+new Date().toLocaleTimeString('pt-BR')}
catch(error){document.getElementById('service').textContent='Indisponível';document.getElementById('updated').textContent=String(error)}}refresh();setInterval(refresh,5000);
</script></body></html>"""
